    infoCostTitle: '비용 산정',
    infoCostDesc: '표시되는 비용은 모델별 공식 Anthropic 가격을 기준으로 한 API 환산 예상치입니다. Claude Code(Max 플랜)는 토큰당 과금이 아니라 정액 구독제입니다. 이 예상치는 사용 패턴을 비교하고 효율성을 파악하는 데 유용합니다.',
    infoDataSourceTitle: '데이터 출처',
    infoDataSourceDesc: 'Claude Code는 세션 데이터를 ~/.claude/projects/ 아래 JSONL 파일로 저장합니다. 싱글 유저 모드(로컬)에서는 트래커가 파일 감시자를 통해 이 파일들을 직접 읽어 메시지별 토큰 수를 추출하고 로컬 SQLite 데이터베이스에 저장합니다. 멀티 유저 모드(호스팅)에서는 경량 동기화 에이전트가 사용자 기기에서 동일한 JSONL 파일을 감시하며 API 키로 새 메시지를 서버에 업로드합니다. 데이터는 서버의 SQLite 데이터베이스에 사용자별로 저장되며 GitHub OAuth 로그인 후 본인만 접근할 수 있습니다.',
