    infoProductivityTitle: '생산성 지표',
    infoProductivityDesc: '생산성 탭은 세션 데이터로부터 효율성 지표를 계산합니다. 분당 토큰: 전체 세션 시간 1분당 평균 출력 토큰. 시간당 라인: 작성+수정된 라인 수를 총 세션 시간으로 나눈 값. 세션당 메시지: 세션당 평균 메시지 수. 라인당 비용: 코드 한 줄당 API 환산 비용. 캐시 절감액: 캐시 읽기 토큰이 전체 입력 가격으로 청구됐을 때와 실제 캐시 읽기 가격의 차이. 코드 비율: 도구 호출(코드 액션)로 끝난 메시지의 비율. 코딩 시간: 세션 지속 시간의 합(마지막 메시지 - 첫 메시지). 병렬 세션은 별도로 합산됩니다. 총 라인 수: Write와 Edit 도구로 발생한 라인 수의 합. 추세 화살표는 선택한 기간을 바로 이전 동일 길이 기간과 비교합니다.',
    infoLinesTitle: '코드 라인 수',
    infoLinesDesc: '대시보드는 Claude의 도구 호출로부터 세 가지 코드 라인 변경을 추적합니다: 작성(초록)은 파일 생성/덮어쓰기 시 Write 도구의 라인 수, 수정(노랑)은 Edit 도구의 교체 텍스트 라인 수, 삭제(빨강)는 Edit 도구의 제거 텍스트 라인 수입니다. 순 변경량 = 작성 + 수정 - 삭제.',
    infoChartInteractivityTitle: '차트 상호작용',
    infoChartInteractivityDesc: '범례 항목을 클릭하면 데이터셋을 숨기거나 표시할 수 있습니다. 범례 선택은 localStorage에 저장되어 새로고침 후에도 유지됩니다. 전역 기간 필터(오늘/7일/30일/전체 기간)도 세션 간 유지됩니다.',
    infoDashboardOverviewTitle: '대시보드 개요',
    infoDashboardOverviewDesc: '개요: KPI 카드, 일별 토큰 사용량, 비용 추이, 모델 분포, 시간대별 활동. 세션: 토큰/라인/비용이 포함된 정렬 가능한 전체 세션 표. 프로젝트: 막대 그래프가 포함된 프로젝트별 내역. 도구: 도구 호출 빈도 차트 및 표. 모델: 시간에 따른 모델 사용량(영역 차트) 및 표. 인사이트: 비용 내역, 누적 비용, 요일별 활동, 캐시 효율, 종료 사유, 세션 효율 분산형 차트, 일별 라인 차트. 정보: 문서, 동기화 에이전트 설정(멀티 유저), 모델 가격.',
