    mCostD: '메시지별로: 토큰 수 / 1,000,000 × 해당 메시지 날짜에 유효했던 구성요소별 가격. 캐시 쓰기는 두 등급이 있습니다 — 5분 캐시는 입력 가격의 1.25배, 1시간 캐시는 2배. Claude Code는 대부분 1시간 캐시에 씁니다.',
